package org.sleepwell.app;

import org.junit.Test;import static org.junit.Assert.*;import java.util.*;

public final class TiltMazeTest {
    @Test public void generatedMazesAlwaysConnectStartToTargetAndKeepSolidOuterWalls(){for(int round=0;round<6;round++)for(int seed=0;seed<100;seed++){TiltMaze maze=new TiltMaze("run-"+seed,0,round);assertFalse(maze.solved());assertTrue(maze.legal(maze.x,maze.y));assertTrue(reachable(maze));for(int n=0;n<maze.size;n++){assertFalse(maze.open(0,n));assertFalse(maze.open(n,0));assertFalse(maze.open(maze.size-1,n));assertFalse(maze.open(n,maze.size-1));}}}
    static boolean reachable(TiltMaze maze){boolean[][] seen=new boolean[maze.size][maze.size];List<int[]> pending=new ArrayList<>();pending.add(new int[]{1,1});seen[1][1]=true;for(int n=0;n<pending.size();n++){int[] p=pending.get(n);if(p[0]==maze.size-2&&p[1]==maze.size-2)return true;for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){int x=p[0]+d[0],y=p[1]+d[1];if(maze.open(x,y)&&!seen[y][x]){seen[y][x]=true;pending.add(new int[]{x,y});}}}return false;}
    @Test public void exactOwnerRegeneratesTheSameWallsAndNewOwnersVary(){Set<String> layouts=new HashSet<>();for(int unit=0;unit<50;unit++){TiltMaze a=new TiltMaze("run",unit,0),b=new TiltMaze("run",unit,0);StringBuilder layout=new StringBuilder();for(int y=0;y<a.size;y++)for(int x=0;x<a.size;x++){assertEquals(a.open(x,y),b.open(x,y));layout.append(a.open(x,y)?1:0);}layouts.add(layout.toString());}assertTrue(layouts.size()>5);}
    @Test public void ballCannotTunnelOrLeaveThroughWalls(){TiltMaze maze=new TiltMaze("run",0,0);for(int n=0;n<100;n++)maze.move(-.5,-.5);assertTrue(maze.x>=1+TiltMaze.RADIUS-1e-6);assertTrue(maze.y>=1+TiltMaze.RADIUS-1e-6);assertTrue(maze.legal(maze.x,maze.y));double x=maze.x,y=maze.y;maze.move(100,100);maze.move(Double.NaN,0);assertEquals(x,maze.x,0);assertEquals(y,maze.y,0);Random random=new Random(42);for(int n=0;n<10000;n++){maze.move(random.nextDouble()-.5,random.nextDouble()-.5);assertTrue(maze.legal(maze.x,maze.y));}}
    @Test public void invalidCheckpointsRejectRatherThanTeleport(){TiltMaze maze=new TiltMaze("run",0,0);assertThrows(IllegalArgumentException.class,()->maze.restore(0,0));assertThrows(IllegalArgumentException.class,()->maze.restore(Double.NaN,1));assertFalse(maze.solved());maze.restore(maze.size-1.5,maze.size-1.5);assertTrue(maze.solved());}
    @Test public void calibratedMotionCanTraverseGeneratedCorridorsWithoutTouchTeleport(){for(int seed=0;seed<30;seed++){TiltMaze maze=new TiltMaze("path-"+seed,0,seed%6);TiltMotion motion=new TiltMotion(1);long time=1;for(int n=0;n<16;n++){motion.sample(time,time,0,0,9.8,0);time+=50_000_000L;}List<int[]> queue=new ArrayList<>();queue.add(new int[]{1,1});Map<Integer,Integer> parent=new HashMap<>();int start=maze.size+1,goal=(maze.size-2)*maze.size+maze.size-2;parent.put(start,-1);for(int n=0;n<queue.size();n++){int[] p=queue.get(n);int key=p[1]*maze.size+p[0];if(key==goal)break;for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){int x=p[0]+d[0],y=p[1]+d[1],next=y*maze.size+x;if(maze.open(x,y)&&!parent.containsKey(next)){parent.put(next,key);queue.add(new int[]{x,y});}}}List<int[]> path=new ArrayList<>();for(int key=goal;key!=-1;key=parent.get(key))path.add(new int[]{key%maze.size,key/maze.size});Collections.reverse(path);for(int[] point:path){int count=0;double targetX=point[0]+.5,targetY=point[1]+.5;while(Math.hypot(maze.x-targetX,maze.y-targetY)>.10&&!maze.solved()&&count++<250){double dx=targetX-maze.x,dy=targetY-maze.y;double[] delta=motion.sample(time,time,Math.abs(dx)>.04?-Math.signum(dx)*2:0,Math.abs(dy)>.04?Math.signum(dy)*2:0,9.8,0);time+=50_000_000L;if(delta!=null)maze.move(delta[0],delta[1]);assertTrue(maze.legal(maze.x,maze.y));}assertTrue(count<250);}assertTrue(maze.solved());}}
}
